    __syncthreads();
    int num_warps = (nthreads + 31) / 32;
    if (warp_id == 0) {
        sum = (lane_id < num_warps) ? s_sum[lane_id] : 0.0;
        sumsq = (lane_id < num_warps) ? s_sumsq[lane_id] : 0.0;
        #pragma unroll
        for (int offset = 16; offset > 0; offset >>= 1) {
            sum += __shfl_down_sync(0xffffffff, sum, offset);
            sumsq += __shfl_down_sync(0xffffffff, sumsq, offset);
        }
        if (lane_id == 0) {
            atomicAdd(&sumOut[m], sum);
            atomicAdd(&sumsqOut[m], sumsq);
        }
    }
}
__global__ void layernorm_apply_vec4(
    const float* __restrict__ X,
    float* __restrict__ Y,
    const float* __restrict__ Gamma,
    const float* __restrict__ Beta,
    const double* __restrict__ sumIn,
    const double* __restrict__ sumsqIn,
    int64_t M, int64_t N, int64_t N4, int64_t chunk, float eps)
{
    int64_t m = blockIdx.x;
    int64_t b = blockIdx.y;
    double sum = sumIn[m];
    double sumsq = sumsqIn[m];
    double mean_d = sum / (double)N;
    double var_d = sumsq / (double)N - mean_d * mean_d;
    if (var_d < 0.0) var_d = 0.0;
    float mean = (float)mean_d;
    float var = (float)var_d;
    float invstd = rsqrtf(var + eps);
    const float* row_x = X + m * N;
    float* row_y = Y + m * N;
    const float4* row_x4 = reinterpret_cast<const float4*>(row_x);
    float4* row_y4 = reinterpret_cast<float4*>(row_y);
    const float4* gamma4 = reinterpret_cast<const float4*>(Gamma);
    const float4* beta4 = reinterpret_cast<const float4*>(Beta);
    const int tid = threadIdx.x;
    const int nthreads = blockDim.x;
    int64_t start = b * chunk;
    int64_t end = start + chunk;
    if (end > N4) end = N4;
    int64_t stride = nthreads;
    int64_t stride4 = stride * 4;
    int64_t i = start + tid;
    // 4-way unrolled loop to improve instruction-level parallelism and
    // hide global memory latency for the elementwise normalization pass.
    for (; i + 3 * stride < end; i += stride4) {
        float4 v0 = row_x4[i];
        float4 v1 = row_x4[i + stride];
        float4 v2 = row_x4[i + 2 * stride];
        float4 v3 = row_x4[i + 3 * stride];
        float4 g0 = gamma4[i];
        float4 g1 = gamma4[i + stride];
        float4 g2 = gamma4[i + 2 * stride];
        float4 g3 = gamma4[i + 3 * stride];
        float4 bb0 = beta4[i];
        float4 bb1 = beta4[i + stride];
        float4 bb2 = beta4[i + 2 * stride];
        float4 bb3 = beta4[i + 3 * stride];
        float4 out0, out1, out2, out3;
        out0.x = (v0.x - mean) * invstd * g0.x + bb0.x;
        out0.y = (v0.y - mean) * invstd * g0.y + bb0.y;
        out0.z = (v0.z - mean) * invstd * g0.z + bb0.z;
        out0.w = (v0.w - mean) * invstd * g0.w + bb0.w;
        out1.x = (v1.x - mean) * invstd * g1.x + bb1.x;
        out1.y = (v1.y - mean) * invstd * g1.y + bb1.y;
        out1.z = (v1.z - mean) * invstd * g1.z + bb1.z;
        out1.w = (v1.w - mean) * invstd * g1.w + bb1.w;
        out2.x = (v2.x - mean) * invstd * g2.x + bb2.x;
        out2.y = (v2.y - mean) * invstd * g2.y + bb2.y;
        out2.z = (v2.z - mean) * invstd * g2.z + bb2.z;
        out2.w = (v2.w - mean) * invstd * g2.w + bb2.w;
        out3.x = (v3.x - mean) * invstd * g3.x + bb3.x;
        out3.y = (v3.y - mean) * invstd * g3.y + bb3.y;
        out3.z = (v3.z - mean) * invstd * g3.z + bb3.z;
        out3.w = (v3.w - mean) * invstd * g3.w + bb3.w;
        row_y4[i] = out0;
        row_y4[i + stride] = out1;
        row_y4[i + 2 * stride] = out2;
        row_y4[i + 3 * stride] = out3;
    }
    for (; i < end; i += stride) {
        float4 v = row_x4[i];
        float4 g = gamma4[i];
        float4 bb = beta4[i];
        float4 out;
        out.x = (v.x - mean) * invstd * g.x + bb.x;
        out.y = (v.y - mean) * invstd * g.y + bb.y;
        out.z = (v.z - mean) * invstd * g.z + bb.z;
        out.w = (v.w - mean) * invstd * g.w + bb.w;
        row_y4[i] = out;
    }
    if (b == gridDim.y - 1) {
        int64_t rem_start = N4 * 4;
        for (int64_t r = rem_start + tid; r < N; r += nthreads) {
            float v = row_x[r];
            float norm = (v - mean) * invstd;
            row_y[r] = norm * Gamma[r] + Beta[r];
        }
    }
}
torch::Tensor layernorm_forward(torch::Tensor x, torch::Tensor gamma, torch::Tensor beta, double eps) {
    TORCH_CHECK(x.is_cuda(), "x must be CUDA");
    TORCH_CHECK(gamma.is_cuda() && beta.is_cuda(), "gamma/beta must be CUDA");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
    TORCH_CHECK(gamma.scalar_type() == at::kFloat, "gamma must be float32");
    TORCH_CHECK(beta.scalar_type() == at::kFloat, "beta must be float32");
    auto x_c = x.contiguous();
    auto gamma_c = gamma.contiguous();
    auto beta_c = beta.contiguous();
    int64_t normalized_numel = gamma_c.numel();
    TORCH_CHECK(beta_c.numel() == normalized_numel, "gamma and beta must have same numel");
    int64_t total = x_c.numel();
    TORCH_CHECK(total % normalized_numel == 0, "x size must be divisible by normalized_shape numel");
    int64_t M = total / normalized_numel;
    int64_t N = normalized_numel;
    auto y = torch::empty_like(x_c);
    int threads = 512;
    if (N < 512) {
        // pick a smaller power-of-two block if N is small
        threads = 32;
        while (threads < N && threads < 512) threads *= 2;
    }
    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
    const float* x_ptr = x_c.data_ptr<float>();
    const float* g_ptr = gamma_c.data_ptr<float>();
    const float* b_ptr = beta_c.data_ptr<float>();
    bool aligned = (reinterpret_cast<uintptr_t>(x_ptr) % 16 == 0) &&
                   (reinterpret_cast<uintptr_t>(g_ptr) % 16 == 0) &&
                   (reinterpret_cast<uintptr_t>(b_ptr) % 16 == 0) &&
                   (reinterpret_cast<uintptr_t>(y.data_ptr<float>()) % 16 == 0);
    if ((N % 4 == 0) && aligned) {
        int64_t N4 = N / 4;
        int64_t blocksPerRow = 64;
        if (blocksPerRow > N4) blocksPerRow = (N4 > 0) ? N4 : 1;
        if (blocksPerRow < 1) blocksPerRow = 1;
        int64_t chunk = (N4 + blocksPerRow - 1) / blocksPerRow;
        if (chunk < 1) chunk = 1;
        blocksPerRow = (N4 + chunk - 1) / chunk;
        if (blocksPerRow < 1) blocksPerRow = 1;
        auto stat_opts = torch::TensorOptions().dtype(torch::kDouble).device(x_c.device());
        auto sum_buf = torch::zeros({M}, stat_opts);
        auto sumsq_buf = torch::zeros({M}, stat_opts);
        dim3 grid((unsigned)M, (unsigned)blocksPerRow);
        dim3 block(threads);
        layernorm_reduce_vec4<<<grid, block, 0, stream>>>(
            x_ptr, sum_buf.data_ptr<double>(), sumsq_buf.data_ptr<double>(),
            M, N, N4, chunk);
        layernorm_apply_vec4<<<grid, block, 0, stream>>>(
            x_ptr, y.data_ptr<float>(), g_ptr, b_ptr,
            sum_buf.data_ptr<double>(), sumsq_buf.data_ptr<double>(),
            M, N, N4, chunk, (float)eps);
    } else {
        dim3 block(threads);
        dim3 grid((unsigned)M);
        layernorm_kernel<float><<<grid, block, 0, stream>>>(
            x_ptr,
            y.data_ptr<float>(),
            g_ptr,
            b_ptr,
            M, N, (float)eps
        );
    }
    auto err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "layernorm_kernel launch failed: ", cudaGetErrorString(err));
    return y;
}
